#!/usr/bin/env bash
# Reproducible native shells generated by the pinned official Flutter SDK.
# These identifiers are local review targets; no store registration or signing.
set -euo pipefail
cd apps/flutter_app
test "$(flutter --version --machine | python3 -c 'import json,sys; print(json.load(sys.stdin)["frameworkVersion"])')" = 3.47.9
flutter create --no-pub --platforms=ios,android --project-name=glam_beauty --org=com.glambeauty.visual .
python3 - <<'PY'
import re
from pathlib import Path
identifier = 'com.glambeauty.visualreview'
path = Path('android/app/build.gradle.kts')
source = path.read_text()
source, count = re.subn(r'applicationId = "[^"]+"', f'applicationId = "{identifier}"', source)
assert count == 1, 'Android application ID must be explicit'
path.write_text(source)
path = Path('ios/Runner.xcodeproj/project.pbxproj')
source = path.read_text()
source, count = re.subn(r'PRODUCT_BUNDLE_IDENTIFIER = com\.glambeauty\.visual\.[^;]+;',
    lambda match: f'PRODUCT_BUNDLE_IDENTIFIER = {identifier}' + ('.RunnerTests;' if 'RunnerTests' in match.group() else ';'), source)
assert count >= 3, 'All iOS app configurations must have a review-only identifier'
path.write_text(source)
path = Path('ios/Runner/Info.plist')
source = path.read_text().replace('<string>Glam Beauty</string>', '<string>GLAM Beauty</string>')
path.write_text(source)
# Use the supplied artwork for the native launch image, not the Flutter mark.
import shutil
launch = Path('ios/Runner/Assets.xcassets/LaunchImage.imageset')
for image in launch.glob('*.png'):
    shutil.copyfile('assets/brand/app-icon.png', image)
# flutter create may add its default counter test. F1 has its own real tests.
counter = Path('test/widget_test.dart')
if counter.exists(): counter.unlink()
PY
